import{_ as e,o as s,c as n,a5 as p}from"./chunks/framework.DJo0M80U.js";const g=JSON.parse('{"title":"HarmonyOS 应用签名体系：密钥、证书、Profile 与公钥指纹","description":"","frontmatter":{"title":"HarmonyOS 应用签名体系：密钥、证书、Profile 与公钥指纹","date":"2026-05-27T00:00:00.000Z","tags":["HarmonyOS","应用签名","DevEco Studio","AppGallery Connect"],"categories":["HarmonyOS"]},"headers":[],"relativePath":"posts/harmonyos教程/HarmonyOS 应用签名体系：密钥、证书、Profile 与公钥指纹.md","filePath":"posts/harmonyos教程/HarmonyOS 应用签名体系：密钥、证书、Profile 与公钥指纹.md","lastUpdated":1790163617000}'),t={name:"posts/harmonyos教程/HarmonyOS 应用签名体系：密钥、证书、Profile 与公钥指纹.md"};function l(o,a,i,c,r,d){return s(),n("div",null,[...a[0]||(a[0]=[p(`<p>可以把鸿蒙签名体系理解成一句话：</p><p><strong>华为要确认：这个应用真的是你这个开发者打出来的、包名没被冒充、权限没乱申请、调试设备/上架环境是被允许的。</strong></p><p>几个东西分别扮演不同角色。</p><hr><h2 id="_1-密钥-你的-私章" tabindex="-1">1. 密钥：你的“私章” <a class="header-anchor" href="#_1-密钥-你的-私章" aria-label="Permalink to &quot;1. 密钥：你的“私章”&quot;">​</a></h2><p><strong>密钥</strong>本质上是一对东西：</p><div class="language-txt vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>私钥：你自己保存，用来给应用签名</span></span>
<span class="line"><span>公钥：别人拿来验证这个签名是不是你签的</span></span></code></pre></div><p>你打包 HAP / APP 时，DevEco Studio 会用你的<strong>私钥</strong>给应用做数字签名。别人不能拿你的公钥去伪造签名，只能用公钥验证“这个包是不是由对应私钥签出来的”。</p><p>所以人话就是：</p><blockquote><p><strong>私钥 = 你盖章用的章。 公钥 = 别人验证这个章是不是真的。</strong></p></blockquote><p>华为文档里也明确说，密钥文件通常是 <code>.p12</code>，里面包含非对称加密用的公钥和私钥，用于数字签名和验证。(<a href="https://developer.huawei.com/consumer/cn/doc/hiai-Guides/signature-information-harmonyos-0000001246159273?utm_source=chatgpt.com" title="配置应用签名信息-开发准备-HarmonyOS-机器学习服务" target="_blank" rel="noreferrer">Huawei Developer</a>)</p><hr><h2 id="_2-密钥库-装-私章-的保险柜" tabindex="-1">2. 密钥库：装“私章”的保险柜 <a class="header-anchor" href="#_2-密钥库-装-私章-的保险柜" aria-label="Permalink to &quot;2. 密钥库：装“私章”的保险柜&quot;">​</a></h2><p><strong>密钥库</strong>通常就是你本地的 <code>.p12</code> 文件。</p><p>它不是单纯一个“密码”，而是一个文件，里面保存你的密钥信息，通常会有密码保护。</p><p>你可以理解为：</p><div class="language-txt vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>密钥库 .p12 = 保险柜</span></span>
<span class="line"><span>私钥 = 保险柜里的私章</span></span>
<span class="line"><span>密码 = 打开保险柜的钥匙</span></span></code></pre></div><p>打包时 DevEco Studio 需要知道：</p><div class="language-txt vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>密钥库文件路径</span></span>
<span class="line"><span>密钥库密码</span></span>
<span class="line"><span>密钥别名</span></span>
<span class="line"><span>密钥密码</span></span></code></pre></div><p>这些信息缺一个，签名就签不了。</p><p>最重要的是：<strong><code>.p12</code> 丢了很麻烦，泄露更严重。</strong></p><p>因为它控制你应用的签名身份。</p><hr><h2 id="_3-证书-华为给你的-身份认证文件" tabindex="-1">3. 证书：华为给你的“身份认证文件” <a class="header-anchor" href="#_3-证书-华为给你的-身份认证文件" aria-label="Permalink to &quot;3. 证书：华为给你的“身份认证文件”&quot;">​</a></h2><p>你自己生成密钥之后，还要向 AppGallery Connect 申请证书。</p><p>证书一般是 <code>.cer</code> 文件。</p><p>它的作用不是拿来签名，而是证明：</p><div class="language-txt vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>这个公钥/签名身份，是华为认可的某个开发者/应用使用的</span></span></code></pre></div><p>你可以理解为：</p><div class="language-txt vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>私钥 = 你的私章</span></span>
<span class="line"><span>证书 = 权威机构给这个章开的证明</span></span></code></pre></div><p>没有证书，系统或平台不知道这个签名身份是否合法。</p><p>鸿蒙调试、发布都会涉及证书。AppGallery Connect 里有调试证书、发布证书等管理入口。(<a href="https://developer.huawei.com/consumer/en/doc/app/agc-help-add-debugcert-0000001914263178?utm_source=chatgpt.com" title="Requesting a Debug Certificate-Debugging Your App ..." target="_blank" rel="noreferrer">Huawei Developer</a>)</p><hr><h2 id="_4-profile-应用的-通行证" tabindex="-1">4. Profile：应用的“通行证” <a class="header-anchor" href="#_4-profile-应用的-通行证" aria-label="Permalink to &quot;4. Profile：应用的“通行证”&quot;">​</a></h2><p><strong>Profile 文件</strong>通常是 <code>.p7b</code>。</p><p>它非常关键，但很多人容易把它和证书混在一起。</p><p>证书回答的是：</p><div class="language-txt vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>你是谁？</span></span></code></pre></div><p>Profile 回答的是：</p><div class="language-txt vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>你这个应用能不能跑？</span></span>
<span class="line"><span>能在哪些设备上跑？</span></span>
<span class="line"><span>用的是哪个包名？</span></span>
<span class="line"><span>用了哪个证书？</span></span>
<span class="line"><span>允许哪些权限？</span></span></code></pre></div><p>华为文档里说，Profile 文件包含应用/元服务的包名、数字证书信息、允许申请的证书权限列表，以及允许调试的设备列表等信息。(<a href="https://developer.huawei.com/consumer/cn/doc/harmonyos-guides/ide-signing?utm_source=chatgpt.com" title="配置调试签名" target="_blank" rel="noreferrer">Huawei Developer</a>)</p><p>所以人话就是：</p><blockquote><p><strong>证书证明“签名身份是真的”； Profile 证明“这个应用在这个场景下被允许运行”。</strong></p></blockquote><p>调试版 Profile 通常会绑定调试设备。</p><p>发布版 Profile 用于正式上架。</p><hr><h2 id="_5-公钥指纹-公钥的-身份证号码" tabindex="-1">5. 公钥指纹：公钥的“身份证号码” <a class="header-anchor" href="#_5-公钥指纹-公钥的-身份证号码" aria-label="Permalink to &quot;5. 公钥指纹：公钥的“身份证号码”&quot;">​</a></h2><p><strong>公钥指纹</strong>通常是 SHA-256 指纹。</p><p>它不是公钥本身，而是从公钥/证书算出来的一串摘要。</p><p>类似：</p><div class="language-txt vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>公钥很长，不方便到处填</span></span>
<span class="line"><span>所以对它做 SHA-256</span></span>
<span class="line"><span>得到一串唯一性很强的指纹</span></span></code></pre></div><p>你可以理解为：</p><div class="language-txt vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>公钥 = 一个人的完整身份资料</span></span>
<span class="line"><span>公钥指纹 = 这个人的身份证号 / 指纹编号</span></span></code></pre></div><p>为什么要填公钥指纹？</p><p>因为很多华为服务要确认：</p><div class="language-txt vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>当前调用我的这个应用，真的是你在 AppGallery Connect 里登记过的应用</span></span></code></pre></div><p>比如 HMS Core、登录、推送、地图、支付、分享等服务，可能需要根据包名 + 签名指纹来识别应用身份。</p><p>AppGallery Connect 文档里也提到，可以添加 SHA-256 证书/公钥指纹，平台也可以根据签名证书计算 SHA-256 指纹。(<a href="https://developer.huawei.com/consumer/cn/doc/app/agc-help-signature-info-0000001628566748?utm_source=chatgpt.com" title="(可选）配置应用签名证书指纹-开发应用-AppGallery Connect ..." target="_blank" rel="noreferrer">Huawei Developer</a>)</p><hr><h2 id="_6-它们完整串起来是这样的" tabindex="-1">6. 它们完整串起来是这样的 <a class="header-anchor" href="#_6-它们完整串起来是这样的" aria-label="Permalink to &quot;6. 它们完整串起来是这样的&quot;">​</a></h2><p>开发时大概流程是：</p><div class="language-txt vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>1. DevEco Studio 生成密钥库 .p12</span></span>
<span class="line"><span>        ↓</span></span>
<span class="line"><span>2. 根据密钥生成证书请求 CSR</span></span>
<span class="line"><span>        ↓</span></span>
<span class="line"><span>3. 去 AppGallery Connect 申请证书 .cer</span></span>
<span class="line"><span>        ↓</span></span>
<span class="line"><span>4. 用证书、包名、设备、权限等生成 Profile .p7b</span></span>
<span class="line"><span>        ↓</span></span>
<span class="line"><span>5. 在 DevEco Studio 配置 .p12 + .cer + .p7b</span></span>
<span class="line"><span>        ↓</span></span>
<span class="line"><span>6. 打包时用私钥签名</span></span>
<span class="line"><span>        ↓</span></span>
<span class="line"><span>7. 手机/系统/AppGallery 校验签名、证书、Profile</span></span></code></pre></div><p>官方文档也提到，构建应用需要用到密钥 <code>.p12</code>、证书 <code>.cer</code> 和 Profile <code>.p7b</code>，然后在 DevEco Studio 中配置签名信息。(<a href="https://developer.huawei.com/consumer/cn/doc/hmscore-common-Guides/harmony-signature-info-0000001167185654?utm_source=chatgpt.com" title="配置应用签名信息-将HMS Core添加至HarmonyOS应用" target="_blank" rel="noreferrer">Huawei Developer</a>)</p><hr><h2 id="_7-一张表说清楚" tabindex="-1">7. 一张表说清楚 <a class="header-anchor" href="#_7-一张表说清楚" aria-label="Permalink to &quot;7. 一张表说清楚&quot;">​</a></h2><table tabindex="0"><thead><tr><th>名称</th><th style="text-align:right;">文件后缀</th><th>人话理解</th><th>主要作用</th></tr></thead><tbody><tr><td>密钥</td><td style="text-align:right;">—</td><td>私章/公章对</td><td>私钥签名，公钥验证</td></tr><tr><td>密钥库</td><td style="text-align:right;"><code>.p12</code></td><td>装私章的保险柜</td><td>保存私钥、公钥等签名材料</td></tr><tr><td>证书</td><td style="text-align:right;"><code>.cer</code></td><td>华为认可的身份证明</td><td>证明这个签名身份合法</td></tr><tr><td>Profile</td><td style="text-align:right;"><code>.p7b</code></td><td>应用通行证</td><td>绑定包名、证书、权限、设备等</td></tr><tr><td>公钥指纹</td><td style="text-align:right;">SHA-256 字符串</td><td>公钥的身份证号</td><td>给华为服务识别应用身份</td></tr></tbody></table><hr><h2 id="_8-debug-和-release-的区别" tabindex="-1">8. Debug 和 Release 的区别 <a class="header-anchor" href="#_8-debug-和-release-的区别" aria-label="Permalink to &quot;8. Debug 和 Release 的区别&quot;">​</a></h2><p>开发调试时一般用：</p><div class="language-txt vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Debug 证书</span></span>
<span class="line"><span>Debug Profile</span></span></code></pre></div><p>它通常会绑定调试设备，所以不是任何设备都能装。</p><p>正式发布时用：</p><div class="language-txt vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Release 证书</span></span>
<span class="line"><span>Release Profile</span></span></code></pre></div><p>这个用于上架和正式分发。</p><p>注意一个非常重要的点：**正式应用的签名不要随便换。**华为 FAQ 提到，HarmonyOS 应用目前不支持变更签名；如果密钥文件丢失，需要生成新密钥、重新申请发布证书和发布 Profile。(<a href="https://developer.huawei.com/consumer/en/doc/app/agc-help-releasefaq-0000001110342644?utm_source=chatgpt.com" title="FAQs-Releasing an App-AppGallery Connect Help Center" target="_blank" rel="noreferrer">Huawei Developer</a>)</p><p>所以 <code>.p12</code> 一定要备份好。</p><hr><h2 id="_9-最容易混淆的地方" tabindex="-1">9. 最容易混淆的地方 <a class="header-anchor" href="#_9-最容易混淆的地方" aria-label="Permalink to &quot;9. 最容易混淆的地方&quot;">​</a></h2><p>你可以这样记：</p><div class="language-txt vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>.p12：我用什么私钥签名？</span></span>
<span class="line"><span>.cer：华为怎么证明这个签名身份？</span></span>
<span class="line"><span>.p7b：这个应用被允许怎么运行？</span></span>
<span class="line"><span>SHA-256 指纹：华为服务怎么快速识别这个应用？</span></span></code></pre></div><p>再简单一点：</p><div class="language-txt vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>密钥库 = 保险柜</span></span>
<span class="line"><span>私钥 = 盖章的章</span></span>
<span class="line"><span>证书 = 章的官方证明</span></span>
<span class="line"><span>Profile = 应用运行通行证</span></span>
<span class="line"><span>公钥指纹 = 这个章的唯一编号</span></span></code></pre></div><hr><h2 id="_10-实际开发中你最该注意的" tabindex="-1">10. 实际开发中你最该注意的 <a class="header-anchor" href="#_10-实际开发中你最该注意的" aria-label="Permalink to &quot;10. 实际开发中你最该注意的&quot;">​</a></h2><p>第一，<code>.p12</code> 和密码一定要保存好，最好进团队密码库或安全备份，不要只放某个人电脑上。</p><p>第二，Debug 和 Release 分开管理，不要拿调试签名去做正式包。</p><p>第三，接华为服务时，包名、签名证书、公钥指纹必须匹配，否则经常出现“本地能跑，服务调用失败”。</p><p>第四，换电脑、换同事、CI/CD 打包时，最容易缺的就是 <code>.p12</code>、密码、<code>.cer</code>、<code>.p7b</code> 这几样。</p>`,88)])])}const u=e(t,[["render",l]]);export{g as __pageData,u as default};
